const services=[{id:'progressiva',name:'Progressiva',duration:120,price:null},{id:'selagem',name:'Selagem',duration:120,price:null}];
const $=id=>document.getElementById(id),key='jaiane-neves-bookings-v1',money=n=>n==null?'A combinar':n.toLocaleString('pt-BR',{style:'currency',currency:'BRL'});
let selectedDate='',selectedTime='',viewMonth=new Date(new Date().getFullYear(),new Date().getMonth(),1);
function localDate(d=new Date()){return `${d.getFullYear()}-${String(d.getMonth()+1).padStart(2,'0')}-${String(d.getDate()).padStart(2,'0')}`}
function readBookings(){try{const data=JSON.parse(localStorage.getItem(key)||'[]');return Array.isArray(data)?data.filter(b=>b&&typeof b.id==='string'&&/^\d{4}-\d{2}-\d{2}$/.test(b.date)&&/^\d{2}:\d{2}$/.test(b.time)&&Number.isFinite(b.duration)&&b.duration>0):[]}catch{return []}}
function saveBookings(data){try{localStorage.setItem(key,JSON.stringify(data));return true}catch{$('formStatus').textContent='Não foi possível salvar. Habilite o armazenamento do navegador.';return false}}
const minutes=t=>Number(t.split(':')[0])*60+Number(t.split(':')[1]),currentService=()=>services.find(s=>s.id===$('service').value);
function slotsFor(date){const s=currentService(),now=new Date();if(!date||date<localDate(now)||new Date(date+'T12:00:00').getDay()===0)return [];const booked=readBookings().filter(b=>b.date===date),slots=[];for(let hour=9;hour<18;hour++){const start=hour*60;if(date===localDate(now)&&start<=now.getHours()*60+now.getMinutes())continue;if(start+s.duration>1080)continue;if(booked.some(b=>start<minutes(b.time)+b.duration&&start+s.duration>minutes(b.time)))continue;slots.push(`${String(hour).padStart(2,'0')}:00`)}return slots}
function renderCalendar(){const now=new Date(),first=new Date(now.getFullYear(),now.getMonth(),1);$('monthLabel').textContent=viewMonth.toLocaleDateString('pt-BR',{month:'long',year:'numeric'});$('prevMonth').disabled=viewMonth<=first;$('calendarDays').replaceChildren();for(let i=0;i<viewMonth.getDay();i++){const blank=document.createElement('span');blank.setAttribute('aria-hidden','true');$('calendarDays').append(blank)}const days=new Date(viewMonth.getFullYear(),viewMonth.getMonth()+1,0).getDate();for(let day=1;day<=days;day++){const d=new Date(viewMonth.getFullYear(),viewMonth.getMonth(),day),date=localDate(d),button=document.createElement('button'),available=slotsFor(date).length>0;button.type='button';button.className='day';button.textContent=day;button.disabled=!available;button.setAttribute('aria-label',`${d.toLocaleDateString('pt-BR',{weekday:'long',day:'numeric',month:'long',year:'numeric'})}${available?'':', indisponível'}`);button.setAttribute('aria-pressed',String(selectedDate===date));if(date===localDate(now)){button.classList.add('today');button.setAttribute('aria-current','date')}if(date===selectedDate)button.classList.add('selected');button.onclick=()=>{selectedDate=date;selectedTime='';$('formStatus').textContent='';renderCalendar();renderTimes()};$('calendarDays').append(button)}}
function updateSummary(){const s=currentService();$('duration').textContent=`${s.duration} minutos`;$('price').textContent=money(s.price);$('selectionSummary').textContent=selectedDate?`${s.name} · ${new Date(selectedDate+'T12:00:00').toLocaleDateString('pt-BR')}${selectedTime?' às '+selectedTime:' · Escolha um horário'}`:'Selecione uma data e um horário.'}
function renderTimes(){const slots=slotsFor(selectedDate);if(!slots.includes(selectedTime))selectedTime='';$('times').replaceChildren();$('selectedDateLabel').textContent=selectedDate?new Date(selectedDate+'T12:00:00').toLocaleDateString('pt-BR',{day:'2-digit',month:'long'}):'';slots.forEach(time=>{const button=document.createElement('button');button.type='button';button.className='time'+(selectedTime===time?' selected':'');button.textContent=time;button.setAttribute('aria-pressed',String(selectedTime===time));button.onclick=()=>{selectedTime=time;$('formStatus').textContent='';renderTimes()};$('times').append(button)});$('timeHint').textContent=!selectedDate?'Selecione um dia no calendário para ver os horários.':slots.length?'Somente horários livres para o serviço selecionado.':'Não há mais horários disponíveis. Escolha outra data.';updateSummary()}
$('prevMonth').onclick=()=>{viewMonth=new Date(viewMonth.getFullYear(),viewMonth.getMonth()-1,1);renderCalendar()};$('nextMonth').onclick=()=>{viewMonth=new Date(viewMonth.getFullYear(),viewMonth.getMonth()+1,1);renderCalendar()};services.forEach(s=>{const option=document.createElement('option');option.value=s.id;option.textContent=`${s.name} · ${money(s.price)}`;$('service').append(option)});$('service').onchange=()=>{selectedTime='';renderCalendar();renderTimes()};renderCalendar();renderTimes();
$('phone').addEventListener('input',e=>{const v=e.target.value.replace(/\D/g,'').slice(0,11);e.target.value=v.length>6?`(${v.slice(0,2)}) ${v.slice(2,-4)}-${v.slice(-4)}`:v.length>2?`(${v.slice(0,2)}) ${v.slice(2)}`:v});
$('bookingForm').onsubmit=e=>{e.preventDefault();const status=$('formStatus');if($('name').value.trim().length<2||$('phone').value.replace(/\D/g,'').length<10){status.textContent='Preencha seu nome e um telefone válido com DDD.';return}if(!selectedDate||!selectedTime){status.textContent='Selecione uma data e um horário disponível.';return}if(!slotsFor(selectedDate).includes(selectedTime)){status.textContent='Esse horário não está mais disponível. Escolha outro.';renderCalendar();renderTimes();return}const s=currentService(),booking={id:globalThis.crypto?.randomUUID?.()||String(Date.now()),service:s.name,duration:s.duration,price:s.price,date:selectedDate,time:selectedTime,name:$('name').value.trim(),phone:$('phone').value};if(!saveBookings([...readBookings(),booking]))return;selectedTime='';renderCalendar();renderTimes();status.textContent=`Reserva salva neste navegador: ${booking.service}, ${new Date(booking.date+'T12:00:00').toLocaleDateString('pt-BR')} às ${booking.time}. Ela não foi enviada ao salão.`};
function renderBookings(){const list=$('bookingList');list.replaceChildren();const bookings=readBookings().sort((a,b)=>(a.date+a.time).localeCompare(b.date+b.time));if(!bookings.length){const p=document.createElement('p');p.className='hint';p.textContent='Você ainda não tem reservas neste navegador.';list.append(p)}bookings.forEach(b=>{const article=document.createElement('article');article.className='saved-booking';const title=document.createElement('strong');title.textContent=b.service;const detail=document.createElement('p');detail.textContent=`${new Date(b.date+'T12:00:00').toLocaleDateString('pt-BR')} às ${b.time} · ${b.name} · ${money(b.price)}`;const cancel=document.createElement('button');cancel.className='cancel';cancel.textContent='Cancelar reserva';cancel.onclick=()=>{if(confirm('Deseja cancelar esta reserva local?')&&saveBookings(readBookings().filter(x=>x.id!==b.id))){renderBookings();renderCalendar();renderTimes()}};article.append(title,detail,cancel);list.append(article)})}
$('myBookings').onclick=()=>{renderBookings();$('bookingsDialog').showModal()};$('closeDialog').onclick=()=>$('bookingsDialog').close();window.addEventListener('storage',e=>{if(e.key===key){renderCalendar();renderTimes();if($('bookingsDialog').open)renderBookings()}});window.addEventListener('focus',()=>{renderCalendar();renderTimes()});
